# ---- таблицы --------------------------------------------------------------
def full_table(var, P):
    rows = []
    for n in sorted(P):
        r = ver[(int(var), n)]
        dom, lv, form, title = P[n]
        cls = {"OK": "ok", "нет ключа в PDF": "calc"}.get(r["status"], "bad")
        st = {"OK": "ключ верен", "нет ключа в PDF": "посчитано (ключа нет)"}.get(r["status"], r["status"])
        rows.append(f"<tr class='{cls}'><td>{n}</td><td>{E(title)}</td><td>{lv}</td><td>{keystr(r['key_pdf'])}</td>"
                    f"<td><b>{keystr(r['computed'])}</b></td><td>{E(st)}</td><td class='note'>{E(r['note'])}</td></tr>")
    return ("<table><thead><tr><th>№</th><th>Тема</th><th>Ур.</th><th>Ключ PDF</th><th>Расчёт</th><th>Статус</th><th>Пояснение</th></tr></thead><tbody>"
            + "".join(rows) + "</tbody></table>")

def lvl(l): return f"<span class='l{l}'>{l}</span>"
cmp_rows = []
for n in range(1, 41):
    a, b = P36896[n], P36898[n]
    d = a[1] - b[1]
    mark = "" if d == 0 else (f"<b>◀ {abs(d)}</b>" if d > 0 else f"<b>{abs(d)} ▶</b>")
    same = "" if GROUP[a[0]] == GROUP[b[0]] else " class='diff'"
    cmp_rows.append(f"<tr{same}><td>{n}</td><td>{E(a[3])}</td><td>{lvl(a[1])}</td><td>{mark}</td><td>{lvl(b[1])}</td><td>{E(b[3])}</td></tr>")

def stats(P, a, b):
    l = [P[i][1] for i in range(a, b + 1)]
    return sum(l) / len(l)
blocks = [("1–10", 1, 10), ("11–20", 11, 20), ("21–25", 21, 25), ("26–30 кейсы", 26, 30), ("31–35 соответствие", 31, 35), ("36–40 множ. выбор", 36, 40), ("Итого 1–40", 1, 40)]
brow = "".join(f"<tr><td>{n}</td><td>{stats(P36896,a,b):.2f}</td><td>{stats(P36898,a,b):.2f}</td><td>{stats(P36896,a,b)-stats(P36898,a,b):+.2f}</td></tr>" for n, a, b in blocks)
groups = sorted({*GROUP.values()})
ca = Counter(GROUP[P36896[i][0]] for i in range(1, 41)); cb = Counter(GROUP[P36898[i][0]] for i in range(1, 41))
grow = "".join(f"<tr><td>{g}</td><td>{ca[g]}</td><td>{cb[g]}</td><td>{ca[g]-cb[g]:+d}</td></tr>" for g in groups)
lc = lambda P: [sum(1 for i in range(1, 41) if P[i][1] == k) for k in (1, 2, 3)]
la, lb = lc(P36896), lc(P36898)

